<script setup>
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
const route=useRoute(), router=useRouter(), {getEventById}=useEvents()
const event=computed(()=>getEventById(route.params.id))
function formatDate(value){if(!value)return 'Date to be announced';const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat('en',{dateStyle:'full',timeStyle:'short'}).format(d)}
</script>
<template>
<div class="detail-page"><button class="back-link" type="button" @click="router.push('/browse/events')">? Back to events</button><section v-if="event" class="detail-shell"><div class="detail-banner"><span class="banner-orbit orbit-a"></span><span class="banner-orbit orbit-b"></span><span class="category-tag">{{event.category}}</span><span class="banner-letter">{{event.category?.slice(0,1)||'G'}}</span></div><div class="detail-content"><div class="main-description"><span class="eyebrow">GATHER TOGETHER</span><h1>{{event.title}}</h1><div class="info-list"><div class="info-item"><span class="info-icon">?</span><div><small>DATE &amp; TIME</small><strong>{{formatDate(event.date)}}</strong></div></div><div class="info-item"><span class="info-icon">?</span><div><small>LOCATION</small><strong>{{event.location}}</strong></div></div><div class="info-item"><span class="info-icon">?</span><div><small>CATEGORY</small><strong>{{event.category}}</strong></div></div></div><h2>About this event</h2><p class="description-text">{{event.desc}}</p></div><aside class="ticket-card"><span class="eyebrow">YOUR SPOT AWAITS</span><h2>Join the experience</h2><p class="price">{{event.price||'Free'}}</p><p class="ticket-copy">{{event.done?'This event has finished and registration is closed.':'Save the date and get ready to connect with your community.'}}</p><button class="register-button" type="button" :disabled="event.done">{{event.done?'Registration closed':'Register interest'}}</button><span class="ticket-note">{{event.done?'This event is now in the archive.':'More details will be shared by the organizer.'}}</span></aside></div></section><section v-else class="not-found"><span class="not-found-icon">?</span><h1>We couldn't find that event</h1><p>It may have been removed, or the link could be out of date.</p><RouterLink to="/browse/events" class="back-button">Explore all events</RouterLink></section></div>
</template>
